#include <iostream>
struct Item { int id{}; int stock{}; };
bool issue(Item& item, int amount) {
    if (item.id < 1 || item.id > 1000 || item.stock < 0 || item.stock > 1000 || amount < 0 || amount > item.stock) { return false; }
    item.stock -= amount;
    return true;
}
int main() {
    Item original{7, 10};
    Item backup = original;
    bool ok = issue(backup, 3);
    std::cout << ok << ' ' << original.stock << ' ' << backup.stock << '\n';
}

